    if (typeof value !== "string") throw new TypeError("invalid writer");
    this._writer = value;
  }
  get body(): string { return this._body; }
  set body(value: string) {
    if (typeof value !== "string") throw new TypeError("invalid body");
    this._body = value;
  }
  get children(): Memo[] { return this._children.slice(); }
  addChild(child: Memo): void { this._children.push(child); }
}

export class Journal {
  private readonly list: Memo[] = [];
  add(memo: Memo): void { this.list.push(memo); }
  get entries(): Memo[] { return this.list.slice(); }
  find(id: number): Memo | undefined {
    return this.list.find(memo => memo.id === id);
  }
}

