import { Memo, Journal } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(action: () => unknown, kind: Function, message: string): void {
  try { action(); } catch (error) {
    assert(error instanceof kind, message);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

const memo = new Memo(0, '', 'body');
equal(memo.id, 0, 'zero id is accepted');
equal(memo.writer, '', 'empty writer string is accepted');
equal(memo.body, 'body', 'body is stored');
memo.id = Number.MAX_SAFE_INTEGER;
memo.writer = 'writer';
memo.body = '';
equal(memo.id, Number.MAX_SAFE_INTEGER, 'maximum safe id is accepted');
equal(memo.writer, 'writer', 'writer setter updates value');
equal(memo.body, '', 'empty body string is accepted');

for (const id of [-1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1]) {
  throws(() => new Memo(id, 'w', 'b'), RangeError, 'constructor rejects invalid id');
  throws(() => { memo.id = id; }, RangeError, 'setter rejects invalid id');
}
throws(() => new Memo(1, 3 as unknown as string, 'b'), TypeError, 'constructor rejects non-string writer');
throws(() => new Memo(1, 'w', null as unknown as string), TypeError, 'constructor rejects non-string body');
throws(() => { memo.writer = false as unknown as string; }, TypeError, 'writer setter validates type');
throws(() => { memo.body = 8 as unknown as string; }, TypeError, 'body setter validates type');

const parent = new Memo(1, 'p', 'parent');
const child = new Memo(2, 'c', 'child');
parent.addChild(child);
const children1 = parent.children;
const children2 = parent.children;
assert(children1 !== children2, 'children getter returns fresh arrays');
equal(children1[0], child, 'addChild retains the supplied instance');
children1.pop();
equal(parent.children.length, 1, 'mutating children copy does not mutate memo');

const journal = new Journal();
const root1 = new Memo(10, 'a', 'root1');
const root2 = new Memo(20, 'b', 'root2');
const deepFirst = new Memo(99, 'first', 'deep');
const nested = new Memo(30, 'n', 'nested');
const laterMatch = new Memo(99, 'later', 'later');
root1.addChild(nested);
nested.addChild(deepFirst);
root2.addChild(laterMatch);
journal.add(root1);
journal.add(root2);
equal(journal.find(10), root1, 'top-level memo is found');
equal(journal.find(30), nested, 'descendant is found');
equal(journal.find(99), deepFirst, 'depth-first pre-order returns first match');
equal(journal.find(404), undefined, 'missing id returns undefined');

const entries1 = journal.entries;
const entries2 = journal.entries;
assert(entries1 !== entries2, 'entries getter returns fresh arrays');
equal(entries1[0], root1, 'entry identities are retained');
entries1.shift();
equal(journal.entries.length, 2, 'mutating entries copy does not mutate journal');

const cyclicJournal = new Journal();
const cycleA = new Memo(101, 'a', 'a');
const cycleB = new Memo(102, 'b', 'b');
cycleA.addChild(cycleB);
cycleB.addChild(cycleA);
cycleA.addChild(cycleB);
cyclicJournal.add(cycleA);
equal(cyclicJournal.find(102), cycleB, 'search finds values in cyclic graph');
equal(cyclicJournal.find(999), undefined, 'search terminates on cycles and repeated instances');
equal(cycleA.children.length, 2, 'search does not mutate child graph');

